/* stylelint-disable stylelint-plugin-mozilla/use-design-tokens */
.account-hub-protocol-select-list {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: calc(4 * var(--space-step));
  margin: 0;
  padding: 0;
  border: 0;
}

.account-hub-protocol-select-card {
  position: relative;
  display: block;
  inline-size: 148px;
  block-size: 127px;
  cursor: pointer;
  box-shadow: 0 1px 2px rgba(0, 1, 2, 0.1);
  border-radius: 8px;
  user-select: none;

  &:has(input:checked) {
    box-shadow: 0 4px 8px rgba(0, 0, 0, 0.14);
  }

  & input[type="radio"] {
    position: absolute;
    inset: 0;
    z-index: 1;
    inline-size: 100%;
    block-size: 100%;
    margin: 0;
    opacity: 0;
    cursor: pointer;
  }

  & .account-hub-protocol-select-card-content {
    display: grid;
    grid-template-rows: 56px 69px;
    box-sizing: border-box;
    block-size: 100%;
    overflow: hidden;
    border: 1px solid var(--color-primary-default);
    border-radius: 8px;
    pointer-events: none;
  }

  & .account-hub-protocol-select-card-header {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: flex-end;
    padding-block: calc(2 * var(--space-step));
    gap: var(--space-step);
    box-sizing: border-box;
    block-size: 57px;
    border-radius: 8px 8px 0 0;
    inline-size: calc(100% + 2px);
    min-inline-size: 0;
    padding-inline: 3px;
    color: var(--color-primary-pressed);
    background-color: var(--color-primary-soft);
    font-size: 1.15rem;
    line-height: 1.1;
    position: relative;
    inset-inline-start: -1px;
    inset-block-start: -1px;
    text-align: center;
    overflow-wrap: anywhere;
  }
